SET current_decision_id = #{decisionId}, status = #{status}, valid_from = #{validFrom}, valid_to = #{validTo},
    review_frequency_code = NULL, next_review_time = NULL, review_status = #{reviewStatus}, version = version + 1, update_time = #{now}
WHERE qualification_id = #{row.qualificationId} AND version = #{row.version}
